<?php require 'config/auth.php';require_login();require 'config/database.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$user_id=$_SESSION['user_id'];$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$category=trim($_POST['category']??'');$location=trim($_POST['location']??'');$item_date=$_POST['item_date']??'';$image=null;if(isset($_FILES['image'])&&$_FILES['image']['error']===UPLOAD_ERR_OK){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','gif'],true)){$image=time().'_'.preg_replace('/[^A-Za-z0-9._-]/','_',$_FILES['image']['name']);move_uploaded_file($_FILES['image']['tmp_name'],'uploads/'.$image);}}$type='found';$stmt=$conn->prepare("INSERT INTO items(user_id,title,description,category,item_type,location,item_date,image,status) VALUES(?,?,?,?,?,?,?,?, 'active')");$stmt->bind_param("isssssss",$user_id,$title,$description,$category,$type,$location,$item_date,$image);if($stmt->execute())$msg='Item posted successfully.';}$pageTitle='Report Found Item';include 'header.php';?><h2>Report Found Item</h2><?php if($msg):?><div class="alert"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><label>Item Title</label><input type="text" name="title" required><label>Description</label><textarea name="description" required></textarea><label>Category</label><input type="text" name="category" required><label>Location</label><input type="text" name="location" required><label>Date</label><input type="date" name="item_date" required><label>Image</label><input type="file" name="image" accept=".jpg,.jpeg,.png,.gif"><button class="btn" type="submit">Submit</button></form><?php include 'footer.php'; ?>